from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-50, 50)
            .Expiration(timedelta(days=0), timedelta(days=90))
        )
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.entry_expiry = None
        self.block_entries_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.pending_entry_signal = False
        self.closes.append(bar.Close)

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5
        slow = sum(self.closes) / 20
        bar_time = bar.EndTime

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
            and (
                (bar_time.hour == 9 and bar_time.minute >= 45)
                or (bar_time.hour >= 10 and bar_time.hour < 14)
                or (bar_time.hour == 14 and bar_time.minute <= 30)
            )
        ):
            self.pending_entry_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, data):
        if self.Portfolio[self.spy].Invested:
            self.Debug(f"Unexpected SPY exercise/assignment holding at {self.Time}; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        self.ManageOpenPosition(data)

        if not self.pending_entry_signal:
            return

        self.pending_entry_signal = False

        if self.block_entries_date == self.Time.date():
            self.Debug(f"Skipped entry at {self.Time}: expiration-day entry block.")
            return

        if self.HasActiveOptionState():
            return

        self.TryEnter(data)

    def TryEnter(self, data):
        if not data.Bars.ContainsKey(self.spy):
            self.Debug(f"Skipped entry at {self.Time}: no current SPY TradeBar.")
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"Skipped entry at {self.Time}: no SPY option chain.")
            return

        spot = data.Bars[self.spy].Close
        chain = data.OptionChains[self.option_symbol]
        today = self.Time.date()

        valid_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if (contract.Expiry.date() - today).days >= 7
            }
        )

        if not valid_expiries:
            self.Debug(f"Skipped entry at {self.Time}: no expiration at least seven calendar days away.")
            return

        expiry = valid_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"Skipped entry at {self.Time}: no eligible call at selected expiration.")
            return

        contract = sorted(candidates, key=lambda x: (x.Strike, str(x.Symbol)))[0]
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket.OrderId <= 0:
            self.Debug(f"Skipped entry at {self.Time}: market order was not accepted.")
            return

        self.held_contract = contract.Symbol
        self.entry_order_id = ticket.OrderId
        self.entry_expiry = contract.Expiry.date()
        self.Debug(f"Entry submitted: {contract.Symbol}, expiry {self.entry_expiry}, strike {contract.Strike}.")

    def ManageOpenPosition(self, data):
        if self.held_contract is None:
            return

        if self.entry_expiry is not None and self.Time.date() >= self.entry_expiry:
            self.block_entries_date = self.Time.date()
            if self.Portfolio[self.held_contract].Invested:
                self.SubmitExit("expiration processing")
            return

        if (
            self.entry_fill_price is not None
            and self.exit_order_id is None
            and data.OptionChains.ContainsKey(self.option_symbol)
        ):
            chain = data.OptionChains[self.option_symbol]
            held = next((x for x in chain if x.Symbol == self.held_contract), None)

            if held is not None and held.BidPrice > 0 and held.AskPrice > 0:
                midpoint = (held.BidPrice + held.AskPrice) / 2
                if midpoint >= self.entry_fill_price * 1.50:
                    self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Direction == OrderDirection.Sell:
                self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket.OrderId > 0:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted for {self.held_contract}: {reason}.")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}."
                )
                self.ScheduleTimeExit(order_event.Symbol)
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order did not fill: {order_event.Symbol}.")
                self.ClearOptionState()

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}."
                )
                self.ClearOptionState()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def ScheduleTimeExit(self, symbol):
        if self.entry_expiry is None:
            return

        previous_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.entry_expiry
        )

        self.Schedule.On(
            self.DateRules.On(previous_day.year, previous_day.month, previous_day.day),
            self.TimeRules.At(15, 45),
            lambda: self.TimeExit(symbol)
        )

    def TimeExit(self, symbol):
        if self.held_contract == symbol and self.Portfolio[symbol].Invested:
            self.SubmitExit("15:45 pre-expiration time stop")

    def HasActiveOptionState(self):
        return (
            self.held_contract is not None
            or self.entry_order_id is not None
            or self.exit_order_id is not None
        )

    def ClearOptionState(self):
        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.entry_expiry = None

