        self.closes = RollingWindow[float](21)
        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.pending_entry_signal = False
        self.held_option = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.block_entries_today = False
        self.block_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.PreExpirationTimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(float(bar.Close))

        if self.closes.Count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self.pending_entry_signal = True

    def OnData(self, data):
        if self.block_date != self.Time.date():
            self.block_date = self.Time.date()
            self.block_entries_today = False

        self.HandleUnexpectedSpyPosition()
        self.HandleExpiration()

        if self.held_option is not None and self.entry_order_id is None:
            if not self.Portfolio[self.held_option].Invested and self.exit_order_id is None:
                self.held_option = None
                self.entry_fill_price = None

        self.CheckProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.block_entries_today:
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        selected_chain = None
        for chain in data.OptionChains.Values:
            if chain.Key == self.option_canonical:
                selected_chain = chain
                break

        if selected_chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in selected_chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiry = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in selected_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.held_option = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
            f"strike {selected.Strike}."
        )

    def CheckProfitTarget(self, data):
        if (
            self.held_option is None or
            self.entry_order_id is not None or
            self.exit_order_id is not None or
            self.entry_fill_price is None or
            not self.Portfolio[self.held_option].Invested
        ):
            return

        contract = self.GetHeldContract(data)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_fill_price:
            self.SubmitExit("profit target")

    def PreExpirationTimeStop(self):
        if (
            self.held_option is None or
            self.entry_order_id is not None or
            self.exit_order_id is not None or
            not self.Portfolio[self.held_option].Invested
        ):
            return

        expiry = self.held_option.ID.Date.date()
        expiry_start = datetime(
            expiry.year, expiry.month, expiry.day,
            0, 0, 0
        )
        previous_open = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            expiry_start, False
        )

        if self.Time.date() == previous_open.date():
            self.SubmitExit("pre-expiration time stop")

    def HandleExpiration(self):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        if self.Time.date() < expiry:
            return

        self.block_entries_today = True

        if self.entry_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
            if ticket is not None:
                ticket.Cancel("Expiration processing")
            self.entry_order_id = None

        if self.Portfolio[self.held_option].Invested and self.exit_order_id is None:
            self.SubmitExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected SPY position from exercise/assignment: "
                f"{quantity}. Liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def GetHeldContract(self, data):
        if self.held_option is None:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    return contract

        return None

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing with exit market order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_option}.")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at "
                    f"{self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry canceled or invalid: {order_event.Symbol}.")
                self.entry_order_id = None
                self.held_option = None
                self.entry_fill_price = None

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}.")
                self.exit_order_id = None
                self.held_option = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Exit canceled or invalid: {order_event.Symbol}.")
                self.exit_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"Assignment detected; liquidating unexpected SPY position: {quantity}."
            )
            self.MarketOrder(self.spy, -quantity)

