        if self.held_symbol is not None:
            self._handle_expiration(data)
            self._handle_scheduled_exit()
            self._handle_profit_target(data)

        bar = data.Bars.get(self.spy_symbol)
        if bar is not None:
            self._update_five_minute_bar(bar, data)

    def _update_five_minute_bar(self, bar, data):
        end_time = bar.EndTime
        session_start = end_time.replace(hour=9, minute=31, second=0, microsecond=0)
        session_end = end_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if end_time < session_start or end_time > session_end:
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        if bucket_minute == 60:
            bucket_end = end_time.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
        else:
            bucket_end = end_time.replace(minute=bucket_minute, second=0, microsecond=0)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.expected_minute_end = bucket_end - timedelta(minutes=4)
            self.bucket_close = None
            self.bucket_count = 0
            self.bucket_valid = True

        if end_time != self.expected_minute_end:
            self.bucket_valid = False

        self.expected_minute_end = end_time + timedelta(minutes=1)
        self.bucket_count += 1
        self.bucket_close = bar.Close

        if end_time != self.bucket_end:
            return

        if self.bucket_valid and self.bucket_count == 5:
            self._on_completed_five_minute_bar(end_time, self.bucket_close, data)

        self.bucket_end = None
        self.expected_minute_end = None
        self.bucket_close = None
        self.bucket_count = 0
        self.bucket_valid = True

    def _on_completed_five_minute_bar(self, end_time, close, data):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            self.fast.IsReady and
            self.slow.IsReady and
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        if not bullish_cross:
            return

        if not (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)):
            return
        if end_time.hour > 14 or (end_time.hour == 14 and end_time.minute > 30):
            return

        self._try_enter(data)

    def _try_enter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return
        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        current_spy_price = self.Securities[self.spy_symbol].Price
        spy_bar = data.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            current_spy_price = spy_bar.Close

        if current_spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no eligible expiration")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call strike")
            return

        contract = sorted(candidates, key=lambda x: (x.Strike, str(x.Symbol)))[0]
        self.entry_symbol = contract.Symbol
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Entry submitted: {0}".format(contract.Symbol))

    def _handle_profit_target(self, data):
        if not self._has_option_position() or self.entry_price is None:
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next((x for x in chain if x.Symbol == self.held_symbol), None)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("Profit target exit submitted")

    def _handle_scheduled_exit(self):
        if not self._has_option_position():
            return
        if self.Time.hour != 15 or self.Time.minute != 45:
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        next_open = self.Securities[self.spy_symbol].Exchange.Hours.GetNextMarketOpen(
            self.Time, False
        )
        if next_open.date() == self.held_symbol.ID.Date.date():
            self._submit_exit("Pre-expiration exit submitted")

    def _handle_expiration(self, data):
        if not self._has_option_position():
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() < expiry_date:
            return

        self.blocked_entry_date = self.Time.date()
        if self.exit_ticket is None or not self._is_open(self.exit_ticket):
            self._submit_exit("Expiration safety exit submitted")

    def _submit_exit(self, message):
        if not self._has_option_position():
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
            self.Debug(message + ": {0}".format(self.held_symbol))

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy_symbol].Invested:
            return

        if self.equity_exit_ticket is None or not self._is_open(self.equity_exit_ticket):
            quantity = self.Portfolio[self.spy_symbol].Quantity
            self.equity_exit_ticket = self.MarketOrder(self.spy_symbol, -quantity)
            self.Debug("Unexpected SPY exercise/assignment handling: liquidation submitted")

    def _has_option_position(self):
        return (
            self.held_symbol is not None and
            self.Portfolio[self.held_symbol].Invested
        )

    def _is_open(self, ticket):
        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_symbol = self.entry_symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.entry_symbol = None
                self.Debug(
                    "Entry filled: {0} @ {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order canceled or invalid")
                self.entry_ticket = None
                self.entry_symbol = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: {0}".format(order_event.FillPrice))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

