from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity("SPY", Resolution.MINUTE)
        self.spy.set_data_normalization_mode(DataNormalizationMode.RAW)

        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option.set_filter(-100, 100, timedelta(0), timedelta(days=365))

        self._closes = RollingWindow[float](20)
        self._previous_fast = None
        self._previous_slow = None
        self._entry_signal = False

        self._held_contract = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_ids = set()
        self._equity_exit_order_id = None
        self._no_entry_date = None

        consolidator = TradeBarConsolidator(self._five_minute_calendar)
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy.symbol, consolidator)

    def _five_minute_calendar(self, dt):
        start = dt.replace(
            minute=(dt.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        self._closes.add(float(bar.close))

        if not self._closes.is_ready:
            return

        fast = sum(self._closes[i] for i in range(5)) / 5.0
        slow = sum(self._closes[i] for i in range(20)) / 20.0

        if self._previous_fast is not None:
            eligible_time = time(9, 45) <= bar.end_time.time() <= time(14, 30)
            if (eligible_time
                    and self._previous_fast <= self._previous_slow
                    and fast > slow):
                self._entry_signal = True

        self._previous_fast = fast
        self._previous_slow = slow

    def on_data(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_protection()
        self._handle_option_exit(slice)

        if self._entry_signal:
            self._entry_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self._no_entry_date == self.time.date():
            return

        if self._held_contract is not None and self.portfolio[self._held_contract].quantity != 0:
            return

        if self._entry_order_id is not None:
            return

        if self.spy.price <= 0:
            self.debug("Skipped entry: invalid SPY price")
            return

        contracts = []
        for chain in slice.option_chains.values:
            for contract in chain:
                if contract.right == OptionRight.CALL:
                    contracts.append(contract)

        if not contracts:
            self.debug("Skipped entry: no option chain")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        expirations = sorted({
            contract.expiry.date()
            for contract in contracts
            if contract.expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.debug("Skipped entry: no expiry at least 7 calendar days away")
            return

        expiry = expirations[0]
        minimum_strike = self.spy.price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.expiry.date() == expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Skipped entry: no qualifying call strike")
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        self._held_contract = selected.symbol
        ticket = self.market_order(selected.symbol, 1)
        self._entry_order_id = ticket.order_id
        self.debug(f"Entry submitted: {selected.symbol}")

    def _handle_option_exit(self, slice):
        if self._held_contract is None:
            return

        holding = self.portfolio[self._held_contract]
        if holding.quantity == 0:
            return

        expiry = self._held_contract.id.date.date()
        if self.time.hour == 15 and self.time.minute == 45:
            if self.time.date() == self._previous_trading_day(expiry):
                self._submit_exit("pre-expiration time stop", False)
                return

        if self._entry_price is None or self._exit_order_ids:
            return

        quote = self._current_contract_quote(slice, self._held_contract)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("profit target", True)

    def _current_contract_quote(self, slice, symbol):
        for chain in slice.option_chains.values:
            for contract in chain:
                if contract.symbol == symbol:
                    bid = float(contract.bid_price)
                    ask = float(contract.ask_price)
                    if bid > 0 and ask > 0:
                        return bid, ask
                    return None
        return None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        while not self.spy.exchange.hours.is_date_open(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _handle_expiration_protection(self):
        if self._held_contract is None:
            return

        if self.portfolio[self._held_contract].quantity == 0:
            return

        expiry_date = self._held_contract.id.date.date()
        if self.time.date() >= expiry_date:
            self._no_entry_date = self.time.date()
            self._submit_exit("expiration protection", True)

    def _submit_exit(self, reason, cancel_other_exits):
        if self._held_contract is None:
            return

        quantity = self.portfolio[self._held_contract].quantity
        if quantity == 0:
            return

        if cancel_other_exits:
            for order_id in list(self._exit_order_ids):
                self.transactions.cancel_order(order_id)

        if self._exit_order_ids:
            return

        ticket = self.market_order(self._held_contract, -quantity)
        self._exit_order_ids.add(ticket.order_id)
        self.debug(f"Exit submitted ({reason}): {self._held_contract}")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy.symbol].quantity
        if quantity == 0 or self._equity_exit_order_id is not None:
            return

        ticket = self.market_order(self.spy.symbol, -quantity)
        self._equity_exit_order_id = ticket.order_id
        self.debug("Unexpected SPY exercise/assignment position; liquidation submitted")

    def on_order_event(self, order_event):
        if order_event.order_id == self._entry_order_id:
            if order_event.status in [OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED]:
                self._entry_price = float(order_event.fill_price)
                self.debug(
                    f"Entry filled: {order_event.symbol} @ {self._entry_price:.2f}"
                )

            if order_event.status in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]:
                self._entry_order_id = None
                if (order_event.status != OrderStatus.FILLED
                        and self._held_contract is not None
                        and self.portfolio[self._held_contract].quantity == 0):
                    self._held_contract = None
                    self._entry_price = None

        if order_event.order_id in self._exit_order_ids:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {order_event.symbol} @ {order_event.fill_price:.2f}")

            if order_event.status in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]:
                self._exit_order_ids.discard(order_event.order_id)
                if (self._held_contract is not None
                        and self.portfolio[self._held_contract].quantity == 0):
                    self._held_contract = None
                    self._entry_price = None

        if order_event.order_id == self._equity_exit_order_id:
            if order_event.status in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]:
                self._equity_exit_order_id = None

