        if self.Time.date() >= expiry_date:
            self.expiration_liquidation_day = self.Time.date()
            if not self.IsOpen(self.exit_ticket):
                self.SubmitExit("expiration protection")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(f"Exit submitted: {reason} ({self.held_option})")

    def GetHeldContract(self, slice):
        if self.option_symbol not in slice.OptionChains or self.held_option is None:
            return None

        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_option:
                return contract

        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, datetime.min.time())
        ):
            candidate -= timedelta(days=1)

        return candidate

    def HasAnyOptionHolding(self):
        for security in self.Securities.Values:
            if (
                security.Type == SecurityType.Option
                and self.Portfolio[security.Symbol].Invested
            ):
                return True
        return False

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.IsOpen(self.equity_cleanup_ticket):
            return

        quantity = self.Portfolio[self.spy].Quantity
        self.equity_cleanup_ticket = self.MarketOrder(self.spy, -quantity)
        self.Debug("Unexpected SPY exercise/assignment position: liquidating")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order canceled or invalid")
                if not self.Portfolio[self.held_option].Invested:
                    self.held_option = None
                    self.entry_price = None
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}")
            self.held_option = None
            self.entry_price = None
            self.entry_ticket = None
            self.exit_ticket = None

        if (
            self.equity_cleanup_ticket is not None
            and order_event.OrderId == self.equity_cleanup_ticket.OrderId
            and order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        ):
            self.equity_cleanup_ticket = None

    def IsOpen(self, ticket):
        return (
            ticket is not None
            and ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )

