from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyOptionCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.entry_order_id = None
        self.entry_price = None
        self.held_contract = None
        self.held_expiry = None
        self.exit_order_id = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.five_minute_consolidator
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(15, 45),
            self.ExitBeforeExpiration
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedSpyHolding()
        self.EnforceExpirationExit()

        self.EvaluateProfitTarget(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime.time()
        if crossed_up and time(9, 45) <= bar_end <= time(14, 30):
            self.pending_entry_signal = True

    def TryEnter(self, slice: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.HasOptionHolding():
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: entry skipped; SPY option chain unavailable.")
            return

        chain = slice.OptionChains[self.option_symbol]
        today = self.Time.date()
        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - today).days >= 7
        })

        if not valid_expirations:
            self.Debug(f"{self.Time}: entry skipped; no expiration at least 7 calendar days away.")
            return

        expiry = valid_expirations[0]
        spy_price = float(self.Securities[self.spy_symbol].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: entry skipped; no call strike at least 1% above SPY "
                f"for {expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish five-minute crossover entry")
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.held_expiry = expiry

        self.Debug(
            f"{self.Time}: entered order for {selected.Symbol}; "
            f"expiry={expiry}, strike={selected.Strike}."
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if (
            self.held_contract is None
            or self.entry_price is None
            or not self.Portfolio[self.held_contract].Invested
            or self.HasOpenExitOrder()
        ):
            return

        if not slice.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")
            self.Debug(
                f"{self.Time}: profit target exit submitted for {self.held_contract}; "
                f"midpoint={midpoint:.2f}, entry={self.entry_price:.2f}."
            )

    def ExitBeforeExpiration(self):
        if (
            self.held_contract is None
            or not self.Portfolio[self.held_contract].Invested
            or self.HasOpenExitOrder()
        ):
            return

        previous_trading_day = self.Securities[
            self.spy_symbol
        ].Exchange.Hours.GetPreviousTradingDay(
            datetime.combine(self.held_expiry, time.min)
        ).date()

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("Pre-expiration time stop")
            self.Debug(
                f"{self.Time}: pre-expiration exit submitted for {self.held_contract}."
            )

    def EnforceExpirationExit(self):
        if (
            self.held_contract is None
            or not self.Portfolio[self.held_contract].Invested
            or self.held_expiry is None
            or self.Time.date() < self.held_expiry
        ):
            return

        self.no_entry_date = self.Time.date()
        if not self.HasOpenExitOrder():
            self.SubmitExit("Expiration safety exit")
            self.Debug(
                f"{self.Time}: expiration safety exit submitted for {self.held_contract}."
            )

    def SubmitExit(self, reason: str):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.HasOpenExitOrder():
            return

        quantity = -self.Portfolio[self.held_contract].Quantity
        ticket = self.MarketOrder(self.held_contract, quantity, tag=reason)
        self.exit_order_id = ticket.OrderId

    def HandleUnexpectedSpyHolding(self):
        if not self.Portfolio[self.spy_symbol].Invested:
            return

        if self.spy_liquidation_order_id is not None and self.IsOrderOpen(
            self.spy_liquidation_order_id
        ):
            return

        self.Debug(
            f"{self.Time}: unexpected SPY equity holding detected from exercise or "
            f"assignment; liquidating."
        )
        ticket = self.Liquidate(self.spy_symbol, tag="Unexpected exercise/assignment cleanup")
        if ticket is not None:
            self.spy_liquidation_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Symbol == self.spy_symbol and order_event.Status == OrderStatus.Filled:
            if self.Portfolio[self.spy_symbol].Invested:
                self.HandleUnexpectedSpyHolding()
            return

        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: entry filled for {order_event.Symbol} at "
                    f"{self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None
                self.entry_price = None
                self.held_contract = None
                self.held_expiry = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled for {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None
                self.entry_order_id = None
                self.entry_price = None
                self.held_contract = None
                self.held_expiry = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def HasOptionHolding(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Invested
        )

    def HasOpenExitOrder(self):
        return (
            self.exit_order_id is not None
            and self.IsOrderOpen(self.exit_order_id)
        )

    def IsOrderOpen(self, order_id: int):
        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

