from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=730))
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end_minutes = None
        self.bucket_closes = {}

        self.held_option = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None

        self.no_entry_date = None

    def OnData(self, slice):
        self._reset_daily_flags()

        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
                self.MarketOrder(self.spy, -quantity)
                self.no_entry_date = self.Time.date()

        self._process_expiration_protection()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._add_spy_minute_bar(spy_bar, slice)

        self._finalize_due_five_minute_bar(slice)

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            if self._is_pre_expiration_time_stop():
                self._submit_exit("pre-expiration time stop")
                return

            self._check_profit_target(slice)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}"
                )
                self.entry_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.exit_order_id = None
                if self.held_option is not None and not self.Portfolio[self.held_option].Invested:
                    self.held_option = None
                    self.held_expiry = None
                    self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment event received; checking SPY position.")
        if self.Portfolio[self.spy].Invested:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.no_entry_date = self.Time.date()

    def _reset_daily_flags(self):
        if self.no_entry_date is not None and self.no_entry_date != self.Time.date():
            self.no_entry_date = None

    def _add_spy_minute_bar(self, bar, slice):
        end = bar.EndTime
        minute_of_day = end.hour * 60 + end.minute

        # Regular-session minute bars ending 09:31 through 16:00.
        if minute_of_day < 571 or minute_of_day > 960:
            return

        bucket_end = 570 + ((minute_of_day - 570 + 4) // 5) * 5

        if self.bucket_date != end.date() or self.bucket_end_minutes != bucket_end:
            if self.bucket_end_minutes is not None:
                self._complete_five_minute_bar(slice)

            self.bucket_date = end.date()
            self.bucket_end_minutes = bucket_end
            self.bucket_closes = {}

        self.bucket_closes[minute_of_day] = float(bar.Close)

    def _finalize_due_five_minute_bar(self, slice):
        if self.bucket_end_minutes is None or self.bucket_date != self.Time.date():
            return

        now_minutes = self.Time.hour * 60 + self.Time.minute
        if now_minutes >= self.bucket_end_minutes:
            self._complete_five_minute_bar(slice)

    def _complete_five_minute_bar(self, slice):
        if self.bucket_end_minutes is None:
            return

        start_minute = self.bucket_end_minutes - 4
        expected_minutes = range(start_minute, self.bucket_end_minutes + 1)

        # Never synthesize a bar: all five constituent minute bars must exist.
        if all(minute in self.bucket_closes for minute in expected_minutes):
            close = self.bucket_closes[self.bucket_end_minutes]
            self._update_averages_and_evaluate_entry(close, slice, self.bucket_end_minutes)

        self.bucket_end_minutes = None
        self.bucket_closes = {}

    def _update_averages_and_evaluate_entry(self, close, slice, end_minutes):
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        end_time = time(end_minutes // 60, end_minutes % 60)
        if end_time < time(9, 45) or end_time > time(14, 30):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.held_option = selected.Symbol
        self.held_expiry = selected.Expiry
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}"
        )

    def _check_profit_target(self, slice):
        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_option:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _is_pre_expiration_time_stop(self):
        if self.held_expiry is None:
            return False

        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        next_trading_date = self.Time.date() + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(next_trading_date):
            next_trading_date += timedelta(days=1)

        return next_trading_date == self.held_expiry.date()

    def _process_expiration_protection(self):
        if (
            self.held_option is None
            or not self.Portfolio[self.held_option].Invested
            or self.held_expiry is None
        ):
            return

        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if (
            self.held_option is None
            or not self.Portfolio[self.held_option].Invested
            or self.exit_order_id is not None
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_option}")

