    def _update_averages_and_evaluate_entry(self, close, slice, end_minutes):
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        end_time = time(end_minutes // 60, end_minutes % 60)
        if end_time < time(9, 45) or end_time > time(14, 30):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.held_option = selected.Symbol
        self.held_expiry = selected.Expiry
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}"
        )

    def _check_profit_target(self, slice):
        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_option:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._submit_exit("50% profit target")

    def _is_pre_expiration_time_stop(self):
        if self.held_expiry is None:
            return False

        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        next_trading_date = self.Time.date() + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(next_trading_date):
            next_trading_date += timedelta(days=1)

        return next_trading_date == self.held_expiry.date()

    def _process_expiration_protection(self):
        if (
            self.held_option is None
            or not self.Portfolio[self.held_option].Invested
            or self.held_expiry is None
        ):
            return

        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if (
