from datetime import timedelta, time


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw,
            extended_market_hours=False
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        self.held_option = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        values = [self.closes[i] for i in range(self.closes.Count)]
        fast = sum(values[:5]) / 5.0
        slow = sum(values[:20]) / 20.0

        bullish_crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        if bullish_crossover and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity > 0:
            self.CheckProfitTarget(slice)
            self.CheckTimeStop()

        if self.pending_entry_bar_end is not None:
            signal_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            if signal_time != self.Time:
                return

            if self.expiration_block_date == self.Time.date():
                return

            if self.held_option is not None and self.Portfolio[self.held_option].Quantity != 0:
                return

            if self.entry_order_id is not None:
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: SPY has no current trade bar.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        eligible_contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                dte = (contract.Expiry.date() - self.Time.date()).days
                if dte >= 7:
                    eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
