            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: SPY option chain unavailable.")
            return

        chain = data.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)
        spot = float(self.Securities[self.spy].Price)

        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry {selected.Expiry.date()} strike {selected.Strike}."
        )

    def _evaluate_option_exit(self, data: Slice):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity <= 0:
            return

        if (
            self._time_stop_date is not None
            and self.Time.date() == self._time_stop_date
            and (self.Time.hour > 15 or (self.Time.hour == 15 and self.Time.minute >= 45))
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self._entry_price is None or self._entry_price <= 0:
            return

        bid, ask = self._option_bid_ask(data, self._held_contract)
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _option_bid_ask(self, data: Slice, symbol: Symbol):
        if symbol in data.QuoteBars:
            quote = data.QuoteBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                return float(quote.Bid.Close), float(quote.Ask.Close)

        if self.option_symbol in data.OptionChains:
            for contract in data.OptionChains[self.option_symbol]:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        return None, None

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing with exit market order")

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self._held_contract}; {reason}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self._equity_exit_order_id = None
            return

        if self._equity_exit_order_id is None:
            ticket = self.MarketOrder(self.spy, -quantity)
            self._equity_exit_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.OrderId == self._entry_order_id:
            if orderEvent.Status == OrderStatus.Filled and orderEvent.FillQuantity > 0:
                self._held_contract = orderEvent.Symbol
                self._entry_price = float(orderEvent.FillPrice)
                self._expiry_date = self._held_contract.ID.Date.date()
                self._time_stop_date = self._previous_trading_day(self._expiry_date)
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {self._held_contract} at {self._entry_price:.2f}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._entry_order_id = None
                self.Debug("Entry order closed without fill.")

        if orderEvent.OrderId == self._exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}.")
                self._reset_option_state()
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_order_id = None

        if orderEvent.OrderId == self._equity_exit_order_id:
            if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self._equity_exit_order_id = None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.DateIsOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _reset_option_state(self):
        self._entry_order_id = None
        self._exit_order_id = None
        self._held_contract = None
        self._entry_price = None
        self._expiry_date = None
        self._time_stop_date = None
